@@ -72,3 +75,52 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  if (!isValidOptionalLimit(message.limit)) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+
+  const cursor = message.before === undefined ? undefined : parseBeforeCursor(message.before);
+  if (message.before !== undefined && cursor === undefined) {
+    return {valid: false, error: 'list_sessions before must have a 1-128 char sessionId and valid updatedAt'};
+  }
+
+  return {valid: true, data: buildListSessionsMessage(message.limit, cursor)};
+}
+
+function isValidOptionalLimit(limit: unknown): limit is number | undefined {
+  if (limit === undefined) return true;
+  if (typeof limit !== 'number') return false;
+  return Number.isInteger(limit) && limit >= 0;
+}
+
+function parseBeforeCursor(rawBefore: unknown): SessionCursor | undefined {
+  if (typeof rawBefore !== 'object' || rawBefore === null) return undefined;
+  if (Array.isArray(rawBefore)) return undefined;
+
+  const candidate = rawBefore as Record<string, unknown>;
+  if (!isValidCursorSessionId(candidate.sessionId)) return undefined;
+  if (!isValidCursorTimestamp(candidate.updatedAt)) return undefined;
+
+  return {updatedAt: candidate.updatedAt, sessionId: candidate.sessionId};
+}
+
+function buildListSessionsMessage(limit: number | undefined, before: SessionCursor | undefined): ListSessionsMessage {
+  const frame: ListSessionsMessage = {type: 'list_sessions'};
+  if (limit !== undefined) frame.limit = limit;
+  if (before !== undefined) frame.before = before;
+  return frame;
+}
+
+function isValidCursorSessionId(sessionId: unknown): sessionId is string {
+  if (typeof sessionId !== 'string') return false;
+  const maxLength = 128;
+  return sessionId.length > 0 && sessionId.length <= maxLength;
+}
+
+function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
+  if (typeof updatedAt === 'number') return Number.isFinite(new Date(updatedAt).getTime());
+  if (typeof updatedAt === 'string') return Number.isFinite(Date.parse(updatedAt));
+  return false;
+}

